buy=intro('WHERE TO BUY A QUADSTICK','The controller that helped<br><em>me compete again.</em>','A thank-you to the people who made this way of playing possible.')+f'''<section class="split dedication"><div><p class="eyebrow">TO THE PEOPLE BEHIND QUADSTICK</p><h2>Thank you for opening<br>up the game.</h2><p>The QuadStick has made a real difference in my life. It gave me a way to get back into gaming, compete with my friends, and enjoy experiences I had been missing.</p><p>I’m grateful to the designers, engineers, and everyone who has helped make this controller possible. The thought and work behind it have opened up opportunities for players like me.</p><p>If you’d like to learn more about the controller or explore buying one, visit the official QuadStick website.</p>{button('Explore QuadStick','https://www.quadstick.com/')}</div><div class="device-image">{pic('quadstick','QuadStick mouth-operated game controller')}<span class="photo-label">SMALL INPUTS. BIG POSSIBILITIES.</span></div></section><aside class="buy-note"><h2>Find the setup that fits you.</h2><p>The official QuadStick website has current models, prices, compatibility details, mounting options, availability, and support.</p><a class="text-link" href="https://www.quadstick.com/">Go to QuadStick.com ↗</a></aside>{cta()}'''
contact=intro('CONTACT ME','Let’s talk<br><em>gaming.</em>','Want to talk gaming, ask about my setup, or connect? Send me an email or find me on social.')+f'''<section class="contact-layout"><div class="contact-main"><p class="eyebrow">SAY HELLO</p><h2>My inbox is open.</h2><a class="email-link" href="mailto:cjsmann092@gmail.com">cjsmann092@gmail.com <span aria-hidden="true">↗</span></a><div class="discord"><div><p class="eyebrow">DISCORD USERNAME</p><strong>quadmann</strong></div><button class="button secondary" id="copy-discord">Copy username</button><span id="copy-status" role="status"></span></div></div><div class="social-list">'''+''.join(f'<a href="{url}"><span class="social-initial" aria-hidden="true">{name[0]}</span><div><h2>{name}</h2><p>@QuadMannGaming</p></div><span aria-hidden="true">↗</span></a>' for name,url in socials)+'</div></section><div class="contact-photo">'+pic('gaming-scene','QuadMann smiling in a colorful gaming scene')+'</div>'

style=intro('MY STYLE','Good games.<br><em>Great shirts.</em>', 'Gaming isn’t the only place I like to bring some personality. I love a good short-sleeve button-down, and a lot of you ask about the shirts I wear in my videos. Here are some of my looks—and where to find them when I can track them down.')
