def layout(title,url,body,description):
 nav=''.join(f'<a href="{u}" {"aria-current=\"page\"" if u==url else ""}>{t}</a>' for t,u in pages)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} | QuadMann Gaming</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#29104d"><meta property="og:title" content="{esc(title)} | QuadMann Gaming"><meta property="og:description" content="{esc(description)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="/" aria-label="QuadMann Gaming home"><img class="header-emblem" src="/assets/qmg-emblem.png" alt="" width="64" height="64"><img class="header-wordmark" src="/assets/quadmann-wordmark.png" alt="" width="210" height="70"></a><button id="menu-toggle" class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu <span aria-hidden="true">☰</span></button><nav id="main-nav" aria-label="Main navigation">{nav}</nav></header><main id="main" tabindex="-1">{body}</main><footer><div class="footer-top"><a class="brand" href="/">QUADMANN <span class="accent">GAMING</span></a><p>A different way to play. The same love for the game.</p></div><div class="footer-bottom"><span>© 2026 QuadMann Gaming</span><nav aria-label="Social links">{''.join(f'<a href="{u}">{n} ↗</a>' for n,u in socials)}<a href="mailto:cjsmann092@gmail.com">Email ↗</a></nav></div></footer><dialog id="media-dialog" aria-labelledby="dialog-title"><div class="dialog-top"><h2 id="dialog-title">Watch video</h2><button id="close-dialog" aria-label="Close media viewer">Close ×</button></div><div id="dialog-content"></div><div id="gallery-controls" hidden><button id="prev-photo">← Previous photo</button><p id="photo-counter" aria-live="polite"></p><button id="next-photo">Next photo →</button></div></dialog></body></html>'''
content=[('Home','/',home,'Meet QuadMann: gaming, competition, and a different way to play with a mouth-operated QuadStick.'),('My Story','/my-story/',story,'From growing up in Raleigh to finding competition again through gaming. Read the story behind QuadMann.'),('How the QuadStick Works','/how-it-works/',how,'See how QuadMann uses a mouth-operated QuadStick, with setup videos and game walkthroughs.'),('My Best Clips','/clips/',clips,'Watch QuadMann Gaming gameplay: Call of Duty, Halo, story-driven adventures, and more.'),('Where to Buy a QuadStick','/quadstick/',buy,'A thank-you to the people behind QuadStick, with a link to explore the official controllers and support.'),('My Style','/my-style/',style,'Colorful shirts and personal style from QuadMann Gaming. Follow along as the verified shirt collection takes shape.'),('FAQ','/faq/',faq,'Answers to common questions about QuadMann: gaming, shirts, LEGO, work, and life.'),('Contact Me','/contact/',contact,'Connect with QuadMann Gaming by email, YouTube, Instagram, TikTok, Twitch, or Discord.')]
for title,url,body,desc in content:
 folder=D/url.strip('/'); folder.mkdir(parents=True,exist_ok=True); (folder/'index.html').write_text(layout(title,url,body,desc),encoding='utf-8')
(D/'gallery.json').write_text(json.dumps([{'src':'/assets/'+n+'.webp','alt':a,'caption':c} for n,a,c in gallery]),encoding='utf-8')
(D/'videos.json').write_text(json.dumps({'checked':'2026-10-18','clips':videos,'tutorials':tutorials},indent=2),encoding='utf-8')
print(f'Built {len(content)} pages.')
